 -->\n\nRoleMapper->RoleModule\n\n\n\n\n\nRoleService\n\nRoleService\n\nRoleModule -->\n\nRoleService->RoleModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/modules/role/role.module.ts\n        \n\n\n\n\n\n        \n            \n                \n                    Providers\n                    \n                        \n                            RoleMapper\n                        \n                        \n                            RoleService\n                        \n                    \n                \n                \n                    Exports\n                    \n                        \n                            RoleService\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        /*\n * @description Product detail entity\n * @author Nhut Tan\n * @since 2025-09-03\n * @version 1.0.0\n */\n\nimport { Module } from '@nestjs/common';\nimport { RoleEntity } from './entities/role.entity';\nimport { TypeOrmModule } from '@nestjs/typeorm';\nimport { RoleRepository } from './repositories/role.repository';\nimport { RoleMapper } from './mappers/role.mapper';\nimport { RoleService } from './role.service';\n\n@Module({\n\timports: [TypeOrmModule.forFeature([RoleEntity])],\n\tproviders: [RoleRepository, RoleMapper, RoleService],\n\tcontrollers: [],\n\texports: [RoleService],\n})\nexport class RoleModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"classes/RoleRepository.html":{"url":"classes/RoleRepository.html","title":"class - RoleRepository","body":"\n                   \n\n\n\n\n\n\n\n\n\n\n\n\n\n  Classes\n  RoleRepository\n\n\n\n        \n            Info\n        \n       